import{z as i,x as n,o as t,c as p,q as B,j as A,D as e,d as l,s as r,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"输出排队与 HOL","description":"","frontmatter":{"title":"输出排队与 HOL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/output-queue-hol.md","filePath":"cs/output-queue-hol.md","lastUpdated":1791413859000}'),d={name:"cs/output-queue-hol.md"};function F(O,E,C,u,h,m){const o=n("Mermaid");return t(),p("div",null,[E[2]||(E[2]=B('<h1 id="输出排队与-hol" tabindex="-1">输出排队与 HOL <a class="header-anchor" href="#输出排队与-hol" aria-label="Permalink to &quot;输出排队与 HOL&quot;">​</a></h1><div class="epigraph"><p>入口 FIFO 里队头帧要去的出口忙，后面去往空闲口的帧也被挡住；虚拟输出排队把目的拆开，结构再调度。</p><footer>—— 据 Karol, Hluchyj and Morgan, 1987；McKeown, iSLIP, IEEE/ACM ToN 1999 整理</footer></div><p><a href="/cs/switch-fabric">上一课</a>给出交叉开关。缺口是<strong>队头阻塞（HOL）</strong>：单 FIFO 输入排队吞吐理论上限约 58.6%（独立均匀目的）。输出排队理想但要结构 \\(N\\) 倍加速。工程折中：VOQ + 匹配调度。本课结束「信号到以太网」课序；下一课序换无线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>输出排队：帧一进结构就进目的口队列，公平、无 HOL，但 \\(N\\) 口同时向同一口发送需要内部 \\(N\\) 倍带宽。输入排队省结构，HOL 严重。VOQ：每个入口为每个出口维护队列，调度器做最大匹配或启发式（iSLIP）。PFC 暂停的是某入口某优先级，可能加重 HOL 若队列未按目的拆开。</p><p><span class="marginnote">数字实例：Karol 等人证明独立均匀目的下，单 FIFO 输入排队的吞吐上限约 58.6%——近一半交换容量被队头阻塞锁死；拆成 VOQ 再配匹配调度，可以逼近 100%。</span></p><p><span class="marginnote">直觉类比：单 FIFO 像机场只开一条安检队，队头那位在为取消的航班徘徊，后面所有赶时间的人一起陪等；VOQ 相当于按目的地分成多条队，谁的目的地有空位就先放谁。</span></p><p>这与 HTTP 后课的队头阻塞同名不同层：这里是交换结构，那里是 TCP 字节流。</p><p><span class="marginnote">Karol 等人给出 HOL 吞吐极限。iSLIP 是可实现的迭代匹配。本课不证极限的全部概率推导。</span></p><h3 id="结构-hol-不是-http-hol" tabindex="-1">结构 HOL 不是 HTTP HOL <a class="header-anchor" href="#结构-hol-不是-http-hol" aria-label="Permalink to &quot;结构 HOL 不是 HTTP HOL&quot;">​</a></h3><p>入 FIFO 队头挡住去往空闲口的帧。VOQ 拆目的再匹配。输出排队理想但要内部加速。PFC 冻结入口会波及无关 VOQ。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画三种排队位置。强调：MAC 学习只选出口，不消除多流争同一出口。LACP 哈希可把流打到不同成员，减轻单口热点，不消除结构 HOL。</p>',13)),(t(),A(s,null,{default:e(()=>[r(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IQ%5B%22%E5%8D%95%20FIFO%20%E5%85%A5%E9%98%9F%22%5D%20--%3E%20HOL%5B%22%E9%98%9F%E5%A4%B4%E9%98%BB%E5%A1%9E%22%5D%0A%20%20VOQ%5B%22%E6%8C%89%E7%9B%AE%E7%9A%84%20VOQ%22%5D%20--%3E%20SCH%5B%22%E5%8C%B9%E9%85%8D%E8%B0%83%E5%BA%A6%22%5D%0A%20%20OQ%5B%22%E8%BE%93%E5%87%BA%E6%8E%92%E9%98%9F%22%5D%20--%3E%20ACC%5B%22%E8%A6%81%E5%86%85%E9%83%A8%E5%8A%A0%E9%80%9F%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"线速承诺依赖调度器在时隙内完成匹配。小包使调度更频繁。巨帧占时长时隙。数据中心 incast 后课是多发送方打同一出口的应用层版本，根子仍是本课的输出热点。",-1)),E[5]||(E[5]=a("p",null,"PAUSE 整口停发，等于冻结该入口所有 VOQ，波及无关出口——PFC 按类缓解，不能从数学上取消 HOL。",-1)),E[6]||(E[6]=a("p",null,"把一个时隙放大看，HOL 怎么浪费空闲出口：FIFO 只认队头，队头去不了，后面去哪都白搭。VOQ 把「按到达顺序」改成「按目的分组」，调度器在每个时隙挑一组互不冲突的队头同时发送。",-1)),(t(),A(s,null,{default:e(()=>[r(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20F1%5B%22%E9%98%9F%E5%A4%B4%E5%B8%A7%EF%BC%9A%E5%8E%BB%E5%87%BA%E5%8F%A3%203%EF%BC%88%E6%9C%AC%E6%97%B6%E9%9A%99%E5%BF%99%EF%BC%89%22%5D%20--%3E%20BLK%5B%22%E6%95%B4%E6%9D%A1%20FIFO%20%E8%A2%AB%E5%AE%83%E6%8C%A1%E4%BD%8F%22%5D%0A%20%20F2%5B%22%E7%AC%AC%E4%BA%8C%E5%B8%A7%EF%BC%9A%E5%8E%BB%E5%87%BA%E5%8F%A3%201%EF%BC%88%E7%A9%BA%E9%97%B2%EF%BC%89%22%5D%20--%3E%20BLK%0A%20%20F3%5B%22%E7%AC%AC%E4%B8%89%E5%B8%A7%EF%BC%9A%E5%8E%BB%E5%87%BA%E5%8F%A3%202%EF%BC%88%E7%A9%BA%E9%97%B2%EF%BC%89%22%5D%20--%3E%20BLK%0A%20%20BLK%20--%3E%20WASTE%5B%22%E5%87%BA%E5%8F%A3%201%E3%80%812%20%E5%B9%B2%E7%AD%89%EF%BC%9A%E5%90%9E%E5%90%90%E6%8E%89%E8%BF%9B%2058.6%25%22%5D%0A%20%20V%5B%22VOQ%EF%BC%9A%E6%8C%89%E7%9B%AE%E7%9A%84%E6%8B%86%E6%88%90%E7%8B%AC%E7%AB%8B%E9%98%9F%E5%88%97%22%5D%20--%3E%20M%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E6%9C%AC%E6%97%B6%E9%9A%99%E6%94%BE%E8%A1%8C%E5%8E%BB%E5%87%BA%E5%8F%A3%201%20%E4%B8%8E%202%20%E7%9A%84%E5%B8%A7%22%5D%0A%20%20M%20--%3E%20SENT%5B%22%E7%A9%BA%E9%97%B2%E5%87%BA%E5%8F%A3%E8%A2%AB%E7%94%A8%E4%B8%8A%EF%BC%8C%E5%90%9E%E5%90%90%E5%9B%9E%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=B('<p><span class="marginnote">常见误区：初学者容易以为把端口提速就能消掉 HOL。这是结构问题：队头不去的出口照样空闲，提速只是缩短时隙；对症的药是把队列按目的拆开（VOQ）再加调度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CIOQ 的精确加速比证明。无线与 OFDM 是下一课序第一课。后课默认：HOL 是输入 FIFO 的结构问题；VOQ 是标准对策。</p><p>不要把交换 HOL 用 TCP 窗口「解决」：窗口在端，结构在跳内。</p><p>下一课<a href="/cs/wifi-frames-ofdm">802.11 帧与 OFDM</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纯输入 FIFO 有 HOL 吞吐上限。</li><li>VOQ + 调度逼近输出排队，免 \\(N\\) 倍加速。</li><li>链路暂停可能冻结无关 VOQ。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Karol et al., 1987；McKeown, 1999。</li></ul>',7))])}const f=i(d,[["render",F]]);export{c as __pageData,f as default};
